標準Pythonだけを使う未実行の合成例。対象DBのAPIや並行制御を模造せず、キー契約の正負期待値だけを検査する。実運用では本文で確定した型・識別契約へ合わせる。この例ではIDは文字列またはnull、kind/key/versionは非空文字列に限定し、Unicode正規化や空白除去を行わない。
```python
import hashlib
import json

FIELDS = ('legacy_target_state_id',
          'legacy_find_candidate_result_id',
          'legacy_cover_evidence_result_id',
          'target_kind', 'target_key', 'distillation_version')

def canonical(row):
    values = [row[f] for f in FIELDS]  # 欠損は拒否
    if any(v is not None and not isinstance(v, str) for v in values[:3]):
        raise ValueError('ID型違反')
    if any(not isinstance(v, str) or not v for v in values[3:]):
        raise ValueError('必須値違反')
    return json.dumps(['queue-key-v1', values], ensure_ascii=False,
                      separators=(',', ':'), allow_nan=False)

def key(row):
    return hashlib.sha256(canonical(row).encode('utf-8')).hexdigest()

base = dict(zip(FIELDS, [None, None, None, 'task', 'A', 'v1']))
reordered = dict(reversed(list(base.items())))
other = dict(base, target_key='B')
assert key(base) == key(reordered)
assert key(base) != key(other)
assert key(base) != key(dict(base, legacy_target_state_id='null'))

# ローカル辞書は検査用。DBの原子的挿入を保証しない。
seen = {}
def register(row, payload):
    k, identity = key(row), canonical(row)
    if k in seen:
        if seen[k] != (identity, payload):
            raise ValueError('同一キーの内容競合')
        return 0
    seen[k] = (identity, payload)
    return 1

assert register(base, 'payload-A') == 1
assert register(reordered, 'payload-A') == 0
assert register(other, 'payload-B') == 1
assert len(seen) == 2
try:
    register(base, 'changed')
except ValueError:
    pass
else:
    raise AssertionError('競合を見逃した')
try:
    canonical(dict(base, target_key=None))
except ValueError:
    pass
else:
    raise AssertionError('不正値を見逃した')
# 全assert通過で正常終了。これはキー例だけの合格。
```
同一複合値を持つ別ジョブを、この関数だけでは識別できない。実データでは元レコードとの対応を別途照合し、意図しない同一化があればキー設計へ戻る。
